def cyc(s):
    H=len(s);W=len(s[0]);cells=[(i,j) for i in range(H) for j in range(W) if s[i][j]]
    idx={p:k for k,p in enumerate(cells)}
    E=0
    for (i,j) in cells:
        for di,dj in ((0,1),(1,0),(1,1),(1,-1)):
            a=(i+di,j+dj)
            if a in idx: E+=1
    V=len(cells)
    ncomp=0; seen=set()
    import collections
    for p in cells:
        if p in seen: continue
        ncomp+=1; q=collections.deque([p]); seen.add(p)
        while q:
            x=q.popleft()
            for di in (-1,0,1):
                for dj in (-1,0,1):
                    if di==dj==0: continue
                    a=(x[0]+di,x[1]+dj)
                    if a in idx and a not in seen: seen.add(a); q.append(a)
    return E - V + ncomp  # cyclomatic number
