                            x,y=a+dr,b+dc
                            if 0<=x<H and 0<=y<W and g[x][y] and (x,y) not in seen:
                                seen.add((x,y)); st.append((x,y))
                rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
                out.append((min(rs),min(cs),max(rs),max(cs),len(pts)))
    return out

def norm(s):
    rows=[[v for v in r] for r in s]
    # trim
    while all(r[0]==0 for r in rows): rows=[r[1:] for r in rows]
    while all(r[-1]==0 for r in rows): rows=[r[:-1] for r in rows]
    while rows[0]==[0]*len(rows[0]): rows.pop(0)
    while rows[-1]==[0]*len(rows[0]): rows.pop()
    return tuple(tuple(r) for r in rows)

